using System.IO.Compression; using EHub.Application.Common.Interfaces.Persistence; using EHub.Application.Common.Interfaces.Storage; using EHub.Contracts.ProductFeedback; using EHub.Domain.Enums; using EHub.Shared.Constants; using EHub.Shared.Errors; using EHub.Shared.Results; using Microsoft.EntityFrameworkCore; using Feedback=EHub.Domain.Entities.ProductFeedback; using Attachment=EHub.Domain.Entities.ProductFeedbackAttachment;
