 public async Task<Result<ProductFeedbackDto>> CreateAsync(CreateProductFeedbackRequest r,Guid userId,string role,CancellationToken ct=default){if(!Sender(role)||!Enum.TryParse<ProductFeedbackCategory>(r.Category,true,out var c)||!Enum.TryParse<ProductFeedbackPriority>(r.Priority,true,out var p)||!Text(r.Title,5,150)||!Text(r.Description,20,3000))return Bad<ProductFeedbackDto>("Feedback fields are invalid.");var title=r.Title.Trim();var description=r.Description.Trim();if(await db.ProductFeedbacks.AnyAsync(x=>x.ReporterUserId==userId&&x.Title==title&&x.Description==description&&x.CreatedAt>=DateTime.UtcNow.AddMinutes(-5),ct))return Bad<ProductFeedbackDto>("This feedback was already sent recently.");var f=new Feedback{ReporterUserId=userId,Category=c,Priority=p,Title=title,Description=description,ContextUrl=string.IsNullOrWhiteSpace(r.ContextUrl)?null:r.ContextUrl.Trim(),CreatedBy=userId};db.ProductFeedbacks.Add(f);await db.SaveChangesAsync(ct);return Result.Success(await Dto(f.Id,ct));}
 public async Task<Result<IReadOnlyCollection<ProductFeedbackDto>>> MineAsync(Guid u,CancellationToken ct=default)=>Result.Success<IReadOnlyCollection<ProductFeedbackDto>>(await Q().Where(x=>x.ReporterUserId==u).OrderByDescending(x=>x.CreatedAt).Select(Map).ToArrayAsync(ct));
 public async Task<Result<IReadOnlyCollection<ProductFeedbackDto>>> InboxAsync(string? c,string? r,string? from,string? to,CancellationToken ct=default){var q=Q();if(Enum.TryParse<ProductFeedbackCategory>(c,true,out var category))q=q.Where(x=>x.Category==category);if(!string.IsNullOrWhiteSpace(r))q=q.Where(x=>x.ReporterUser.UserRoles.Any(ur=>ur.Role.Name==r));if(DateTime.TryParse(from,out var a))q=q.Where(x=>x.CreatedAt>=a.ToUniversalTime());if(DateTime.TryParse(to,out var b))q=q.Where(x=>x.CreatedAt<=b.ToUniversalTime());return Result.Success<IReadOnlyCollection<ProductFeedbackDto>>(await q.OrderBy(x=>x.IsArchived).ThenBy(x=>x.IsRead).ThenByDescending(x=>x.CreatedAt).Select(Map).ToArrayAsync(ct));}
 public async Task<Result<ProductFeedbackDto>> GetAsync(Guid id,Guid u,string role,CancellationToken ct=default){var f=await db.ProductFeedbacks.FirstOrDefaultAsync(x=>x.Id==id,ct);if(f is null)return Missing<ProductFeedbackDto>();if(!Admin(role)&&f.ReporterUserId!=u)return Denied<ProductFeedbackDto>();if(Admin(role)&&!f.IsRead){f.IsRead=true;f.ReadAtUtc=DateTime.UtcNow;f.ReadByUserId=u;await db.SaveChangesAsync(ct);}return Result.Success(await Dto(id,ct));}
 public async Task<Result> DeleteAsync(Guid id,CancellationToken ct=default){var f=await db.ProductFeedbacks.Include(x=>x.Attachments).FirstOrDefaultAsync(x=>x.Id==id,ct);if(f is null)return Result.Failure(ErrorCodes.ProductFeedbackNotFound,"Feedback was not found.");foreach(var a in f.Attachments)await files.DeleteAsync(a.CloudinaryPublicId,ct);db.ProductFeedbacks.Remove(f);await db.SaveChangesAsync(ct);return Result.Success();}
 public async Task<Result> DeleteAllAsync(CancellationToken ct=default){var all=await db.ProductFeedbacks.Include(x=>x.Attachments).ToListAsync(ct);foreach(var f in all){foreach(var a in f.Attachments)await files.DeleteAsync(a.CloudinaryPublicId,ct);}db.ProductFeedbacks.RemoveRange(all);await db.SaveChangesAsync(ct);return Result.Success();}
 public async Task<Result<ProductFeedbackAttachmentDto>> UploadAsync(Guid id,Stream s,string name,long len,Guid u,string role,CancellationToken ct=default){var f=await db.ProductFeedbacks.FirstOrDefaultAsync(x=>x.Id==id,ct);if(f is null)return Missing<ProductFeedbackAttachmentDto>();if(!Sender(role)||f.ReporterUserId!=u)return Denied<ProductFeedbackAttachmentDto>();if(len<=0||len>Max||await db.ProductFeedbackAttachments.CountAsync(x=>x.ProductFeedbackId==id,ct)>=3)return Bad<ProductFeedbackAttachmentDto>("Attachment limit or file size is invalid.");var ext=Path.GetExtension(name);if(!Types.TryGetValue(ext,out var mime))return Bad<ProductFeedbackAttachmentDto>("Only PNG, JPG, WEBP, PDF, DOCX, and PPTX files are accepted.");await using var buffer=new MemoryStream();await s.CopyToAsync(buffer,ct);var bytes=buffer.ToArray();if(!Signature(bytes,ext))return Bad<ProductFeedbackAttachmentDto>("The file does not match its declared format.");var upload=await files.UploadAsync(new MemoryStream(bytes,false),Path.GetFileName(name),mime,id,0,ct);if(upload.IsFailure)return Result.Failure<ProductFeedbackAttachmentDto>(upload.Error);var a=new Attachment{ProductFeedbackId=id,OriginalName=Path.GetFileName(name),MimeType=mime,FileSize=bytes.Length,FileUrl=upload.Value.SecureUrl,CloudinaryPublicId=upload.Value.PublicId,CreatedBy=u};db.ProductFeedbackAttachments.Add(a);await db.SaveChangesAsync(ct);return Result.Success(new ProductFeedbackAttachmentDto{Id=a.Id,OriginalName=a.OriginalName,MimeType=a.MimeType,FileSize=a.FileSize});}
 public async Task<Result<SubmissionFileDownloadResult>> DownloadAsync(Guid id,Guid aid,Guid u,string role,CancellationToken ct=default){var f=await db.ProductFeedbacks.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id,ct);if(f is null)return Missing<SubmissionFileDownloadResult>();if(!Admin(role)&&f.ReporterUserId!=u)return Denied<SubmissionFileDownloadResult>();var a=await db.ProductFeedbackAttachments.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==aid&&x.ProductFeedbackId==id,ct);return a is null?Result.Failure<SubmissionFileDownloadResult>(ErrorCodes.CommonNotFoundError,"Attachment was not found."):await files.DownloadAsync(a.FileUrl,ct);}
 IQueryable<Feedback> Q()=>db.ProductFeedbacks.AsNoTracking().Include(x=>x.ReporterUser).ThenInclude(x=>x.UserRoles).ThenInclude(x=>x.Role).Include(x=>x.Attachments);async Task<ProductFeedbackDto> Dto(Guid id,CancellationToken ct)=>await Q().Where(x=>x.Id==id).Select(Map).FirstAsync(ct);static readonly System.Linq.Expressions.Expression<Func<Feedback,ProductFeedbackDto>> Map=x=>new(){Id=x.Id,Category=x.Category.ToString(),Priority=x.Priority.ToString(),Title=x.Title,Description=x.Description,ContextUrl=x.ContextUrl,ReporterName=x.ReporterUser.FullName,ReporterEmail=x.ReporterUser.Email,ReporterRole=x.ReporterUser.UserRoles.Select(r=>r.Role.Name).FirstOrDefault()??"",IsRead=x.IsRead,IsAcknowledged=x.IsAcknowledged,IsArchived=x.IsArchived,CreatedAtUtc=x.CreatedAt,Attachments=x.Attachments.Select(a=>new ProductFeedbackAttachmentDto{Id=a.Id,OriginalName=a.OriginalName,MimeType=a.MimeType,FileSize=a.FileSize}).ToArray()};static bool Sender(string r)=>r.Equals(SystemRoles.Student,StringComparison.OrdinalIgnoreCase)||r.Equals(SystemRoles.Lecturer,StringComparison.OrdinalIgnoreCase)||r.Equals(SystemRoles.Mentor,StringComparison.OrdinalIgnoreCase);static bool Admin(string r)=>r.Equals(SystemRoles.Admin,StringComparison.OrdinalIgnoreCase);static bool Text(string? x,int min,int max)=>!string.IsNullOrWhiteSpace(x)&&x.Trim().Length>=min&&x.Trim().Length<=max;static Result<T> Bad<T>(string m)=>Result.Failure<T>(ErrorCodes.ProductFeedbackValidationError,m);static Result<T> Missing<T>()=>Result.Failure<T>(ErrorCodes.ProductFeedbackNotFound,"Feedback was not found.");static Result<T> Denied<T>()=>Result.Failure<T>(ErrorCodes.ProductFeedbackAccessDenied,"You do not have access to this feedback.");static bool Signature(byte[] b,string e)=>e.Equals(".pdf",StringComparison.OrdinalIgnoreCase)?b.Length>=5&&b.AsSpan(0,5).SequenceEqual("%PDF-"u8):e.Equals(".png",StringComparison.OrdinalIgnoreCase)?b.Length>=8&&b[0]==137&&b[1]==80&&b[2]==78&&b[3]==71:e.Equals(".jpg",StringComparison.OrdinalIgnoreCase)||e.Equals(".jpeg",StringComparison.OrdinalIgnoreCase)?b.Length>=3&&b[0]==255&&b[1]==216&&b[2]==255:b.Length>=4&&b[0]==80&&b[1]==75; }
